/* 14. alpha */
const Alpha: React.FC<SceneProps> = ({t, dur}) => {
  const cards = [
    {k: 'opaque', rgba: E.alpha.opaque.px, v: E.alpha.opaque.cd},
    {k: 'straight', rgba: E.alpha.straight.px, v: E.alpha.straight.cd},
    {k: 'premultiplied-looking', rgba: E.alpha.premult.px, v: E.alpha.premult.cd},
    {k: 'dark', rgba: E.alpha.dark.px, v: E.alpha.dark.cd},
    {k: 'all zero', rgba: E.alpha.zero.px, v: E.alpha.zero.cd},
  ];
  const cw = 320, gap = 28, x0 = (W - (5 * cw + 4 * gap)) / 2;
  return (
    <>
      <Head over={`Alpha mode, colordetect ${E.version8}`} title="Provable, or undetermined." o={rv(t, dur, 0.02, 0.1)} />
      {cards.map((c, i) => {
        const x = x0 + i * (cw + gap), o = rv(t, dur, 0.1 + i * 0.11, 0.2 + i * 0.11), col = VERDICT_COLOR[c.v] ?? C.dim;
        return (
          <React.Fragment key={c.k}>
            <Panel x={x} y={250} w={cw} h={420} color={col} o={o} />
            <Swatch x={x + (cw - 150) / 2} y={280} rgba={c.rgba} o={o} />
            <div style={{position: 'absolute', left: x, top: 450, width: cw, textAlign: 'center', fontFamily: F.mono, fontSize: 24, color: C.dim, opacity: o}}>{c.rgba.join(',')}</div>
            <div style={{position: 'absolute', left: x + 10, top: 488, width: cw - 20, textAlign: 'center', fontFamily: F.sans, fontSize: 24, fontWeight: 600, color: C.text, opacity: o, lineHeight: 1.15}}>{c.k}</div>
            <Chip x={x + 20} y={580} w={cw - 40} text={c.v} color={col} o={o} size={26} />
          </React.Fragment>
        );
      })}
      <div style={{position: 'absolute', left: 0, top: 710, width: W, textAlign: 'center', fontFamily: F.sans, fontSize: 30, fontWeight: 700, color: C.text, opacity: rv(t, dur, 0.7, 0.8)}}>{`One bad pixel in 1 of ${E.alpha.bad.frames} frames: ${E.alpha.bad.cd}`}</div>
      <Mid y={775} size={26} o={rv(t, dur, 0.82, 0.92)}>A channel above its alpha proves straight. Everything else stays open.</Mid>
    </>
  );
};

