/* 17. sheet */
const Sheet: React.FC<SceneProps> = ({t, dur}) => {
  const cols = [260, 690, 1160, 1590];
  const head = ['', 'ffprobe', 'signalstats', 'colordetect'];
  const rows: string[][] = [
    ['Looks at', 'the tag', 'the pixels', 'the pixels, luma only'],
    ['Builds', `${E.version6} and ${E.version8}`, `${E.version6} and ${E.version8}`, `${E.version8} only`],
    ['Proves full range', 'no', 'yes', 'yes'],
    ['Proves limited range', 'no', 'no', 'no'],
    ['Alpha mode', 'no field', 'alpha plane min, max', 'opaque, straight'],
  ];
  const tone = (r: number, c: number) => (r === 3 ? C.red : c === 0 ? C.dim : (rows[r][c] === 'yes' ? C.green : rows[r][c] === 'no' ? C.amber : C.text));
  return (
    <>
      <Head over="Cheat sheet" title="Witnesses and what they prove." o={rv(t, dur, 0.02, 0.1)} />
      {head.map((h, c) => <div key={c} style={{position: 'absolute', left: cols[c] - 190, top: 250, width: 380, textAlign: 'center', fontFamily: F.mono, fontSize: 32, fontWeight: 700, color: C.cyan, opacity: rv(t, dur, 0.1, 0.2)}}>{h}</div>)}
      <div style={{position: 'absolute', left: 90, top: 300, width: W - 180, height: 3, background: C.line, opacity: rv(t, dur, 0.1, 0.2)}} />
      {rows.map((r, ri) => r.map((cell, c) => (
        <div key={`${ri}-${c}`} style={{position: 'absolute', left: cols[c] - 200, top: 330 + ri * 100, width: 400, textAlign: c === 0 ? 'right' : 'center', fontFamily: F.sans, fontSize: 30, fontWeight: c === 0 ? 700 : 800, color: tone(ri, c), opacity: rv(t, dur, 0.2 + ri * 0.12, 0.3 + ri * 0.12), paddingRight: c === 0 ? 60 : 0, boxSizing: 'border-box'}}>{cell}</div>
      )))}
    </>
  );
};

